 private void openWeeklyAlarm(NapProfilesWeekly.Group selected,int alarmId){
  run(runtime->{
   NapProfilesWeekly.Group current=null;
   for(NapProfilesWeekly.Group candidate:NapProfilesWeekly.groups(runtime.context))if(candidate.id.equals(selected.id)&&candidate.nonce.equals(selected.nonce)){current=candidate;break;}
   if(current==null||current.rows.stream().noneMatch(row->row.id==alarmId))throw new IllegalArgumentException("This weekly relation was removed or changed. Open all alarms to review current entries.");
   try(Store store=Records.open(runtime.context)){
    Alarm actual=store.alarm(alarmId);
    if(actual==null||!current.nonce.equals(NapProfilesWeekly.nonce(actual))||!NapProfilesWeekly.owns(runtime.context,actual))throw new IllegalArgumentException("This alarm was deleted, detached or changed. Open all alarms to review it independently.");
    return new OpenWeeklyAlarm(current.id,actual.json().toString());
   }
  });
 }
 private void openDate(){LocalDate initial;try{initial=day.isEmpty()?LocalDate.now().plusDays(1):LocalDate.parse(day);}catch(RuntimeException invalid){initial=LocalDate.now().plusDays(1);}if(calendar!=null)calendar.close();Bundle restore=restoredCalendar;restoredCalendar=null;calendar=new RecordCalendar(this,"Profile apply date",initial,restore,date->{day=date.toString();review=null;error="";render();},null);}
